                 const char **elem_rtrn, const char **field_rtrn,
                 ExprDef **index_rtrn) {
    if (!expr) {
        return false;
    }

    switch (expr->type) {
        case EXPR_IDENT: {
            *elem_rtrn = expr->ident.name;
            *field_rtrn = NULL;
            *index_rtrn = NULL;
            return true;
        }

        case EXPR_FIELD_REF: {
            *elem_rtrn = expr->field_ref.base->ident.name;
            *field_rtrn = expr->field_ref.field;
            *index_rtrn = NULL;
            return true;
        }

        case EXPR_ARRAY_REF: {
            *elem_rtrn = expr->array_ref.base->ident.name;
            *field_rtrn = NULL;
            *index_rtrn = expr->array_ref.index;
            return true;
        }

        default: {
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR,
                            "Unexpected operator in LHS resolution");
            return false;
        }
    }
}

